base_files.assets/worlds/probe_collapse_min.toml:
# Probe world for issue #1040 — a structure WARNING, then FALLING, then leaving
# a rescue behind it.
#
# This is the minimal, operations-free successor to the retired `probe_collapse`
# world (#1164, S11a). The four claims #1040 owns are all here — a warning
# ladder, a condition floor that removes the structure, a reaction inside the
# final window that prevents it, and a rescue that completes — and none of them
# is about an operation verb. The retired world drove the SAVE with a `stabilise`
# and the RESCUE with a `tow`; both are re-expressed here as scripted
# `repair_infrastructure` payouts on the same clock, so the world needs no
# `[operations]` capability at all.
#
# TWO HEADS, SIDE BY SIDE, is how it holds claims 2 and 3 apart in one run. Both
# are the same `skyhook.toml` on the same strain schedule; the only difference
# between them is that ONE IS SAVED by a scripted repair on the third warning.
#
# EACH HEAD AUTHORS ITS OWN THRESHOLD LADDER, replacing the template's wholesale
# (arrays replace at the instance layer): a threshold `flag` is the scenario's
# namespace, so two heads inheriting one ladder would overwrite each other.
#
# ── The authored timeline, in mission seconds ────────────────────────────────
#
# Both heads open on 30 of 100 points and lose 2 every 2 seconds.
#
#   t=1    the strain begins; both heads step 30 → 28 → 26 …
#   t=5    24 — under 25 %: `*_bearing` falls        WARNING ONE (both)
#   t=11   18 — under 19 %: `*_tensioned` falls      WARNING TWO (both)
#   t=17   12 — under 13 %: `*_holding` falls        WARNING THREE (both), and the
#          saved side schedules a repair FOUR SECONDS OUT — the window a crew has
#          to react in, expressed as a script call so the probe needs no console.
#   t≈21   the scheduled repair pays 26 points into a head sitting on 8, which
#          carries it back over the FIRST rung's restore line. The flag rising IS
#          the save: the watch closes and the strain stops.
#   t=23   6 — under 7 %: the LOST side's `*_stable` falls. `destroy_entity` takes
#          it, `on_destroyed` chains, the projection deadline is called off, and
#          the epilogue opens.
#   t=25   a survivor lighter is spawned into the debris on 20 of 100 points.
#   t=27   the rescue begins; a repair is scheduled three seconds out.
#   t=30   the payout carries the lighter over its line: `on_flag_set` records
#          the recovery.
#   t=35   the epilogue resolves, ten seconds after the craft came out of the
#          wreck, and completes its objective.
#
# EVERY REGISTRATION THAT READS A FLAG GOING **UP** CARRIES A `when`: a condition
# track publishes its `initial_flags` on its first tick, so every rung is UP at
# load and a flag trigger is single-shot. `when` suppresses a firing WITHOUT
# consuming the trigger.

[global]
seed = 1040
ai_helm_tick_hz = 30.0

[player_spawn]
position = [0.0, 0.0, 0.0]

[anchors]
# Where the lost head's survivors end up. Off the head, because the wreck is
# where the ribbon was.
probe_debris = [900.0, 0.0, 240.0]

# The player ship, present because a world needs one. It does no work here.
[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "player-ship"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

# ── The head that is saved ───────────────────────────────────────────────────
#
# Its ladder is the template's shape at a quarter of the template's numbers,
# because this probe drives a head from 30 points rather than from 48.
[[entity]]
template_path = "assets/entities/skyhook.toml"
id = "hook_saved"
name = "world.probe_collapse.entity.hook_saved.name"
transform = { position = [400.0, 0.0, 0.0] }

[entity.overrides.infrastructure]
condition = 30.0

[[entity.overrides.infrastructure.capacity]]
id = "probe_saved_berths"
amount = 2

[[entity.overrides.infrastructure.threshold]]
flag = "probe_saved_bearing"
fails_below = 0.25

[[entity.overrides.infrastructure.threshold]]
flag = "probe_saved_tensioned"
fails_below = 0.19

[[entity.overrides.infrastructure.threshold]]
flag = "probe_saved_holding"
fails_below = 0.13

[[entity.overrides.infrastructure.threshold]]
flag = "probe_saved_stable"
fails_below = 0.07

# ── The head that is lost ────────────────────────────────────────────────────
#
# Identical, to the point. Nobody saves it.
[[entity]]
template_path = "assets/entities/skyhook.toml"
id = "hook_lost"
name = "world.probe_collapse.entity.hook_lost.name"
transform = { position = [800.0, 0.0, 0.0] }

[entity.overrides.infrastructure]
condition = 30.0

[[entity.overrides.infrastructure.capacity]]
id = "probe_lost_berths"
amount = 2

[[entity.overrides.infrastructure.threshold]]
flag = "probe_lost_bearing"
fails_below = 0.25

[[entity.overrides.infrastructure.threshold]]
flag = "probe_lost_tensioned"
fails_below = 0.19

[[entity.overrides.infrastructure.threshold]]
flag = "probe_lost_holding"
fails_below = 0.13

[[entity.overrides.infrastructure.threshold]]
flag = "probe_lost_stable"
fails_below = 0.07

# The projected failure, one second AFTER the arithmetic says the lost head
# crosses its floor, so the run proves the collapse CANCELS it rather than races
# it.
[[deadline]]
id = "probe_projection_due"
label = "world.probe_collapse.deadline.projection.label"
due_secs = 24
visible = true

[script]
setup = """
on_timer(1, "on_strain");

on_deadline("probe_projection_due", "on_projection_due");

// The two ladders, read as flags falling.
on_flag_cleared("probe_saved_bearing", "on_saved_warning_one");
on_flag_cleared("probe_saved_tensioned", "on_saved_warning_two");
on_flag_cleared("probe_saved_holding", "on_saved_warning_three");
on_flag_cleared("probe_saved_stable", "on_saved_gives_way");

on_flag_cleared("probe_lost_bearing", "on_lost_warning_one");
on_flag_cleared("probe_lost_tensioned", "on_lost_warning_two");
on_flag_cleared("probe_lost_holding", "on_lost_warning_three");
on_flag_cleared("probe_lost_stable", "on_lost_gives_way");

// THE SAVE, read off the top rung coming back up. Both flags are UP at load, so
// each registration carries the `when` that keeps its single-shot trigger armed
// until the real crossing.
on_flag_set("probe_saved_bearing", "on_saved_stands_down")
    .when("counter(probe_watch) > 0");
on_flag_set("probe_lost_bearing", "on_lost_stands_down")
    .when("counter(probe_watch) > 0");

// The collapse's consequences, chained off the REMOVAL rather than written
// beside it (#1033).
on_destroyed("world.probe_collapse.entity.hook_lost.name", "on_lost_head_gone");

// The rescue's completion signal. The survivor spawns UNDER its line, so the
// flag is down from its first tick and no `when` is needed.
on_flag_set("probe_survivor_secured", "on_survivor_recovered");

// The strain: 2 condition points off BOTH heads every 2 seconds, re-arming
// itself while the watch is open. One beat drives two ladders, so the two heads
// cannot drift apart for any reason other than the save.
fn on_strain(ctx) {
    if ctx.flags.probe_stopped > 0 { return; }
    ctx.flags.probe_watch = 1;
    if ctx.flags.probe_saved_held == 0 {
        ctx.effects.damage_infrastructure("world.probe_collapse.entity.hook_saved.name", 2);
    }
    if ctx.flags.probe_lost_gone == 0 {
        ctx.effects.damage_infrastructure("world.probe_collapse.entity.hook_lost.name", 2);
    }
    ctx.flags.increment("strain_beats", 1);
    ctx.schedule.after(2, |ctx| { on_strain(ctx); });
}

fn on_saved_warning_one(ctx)   { ctx.flags.increment("saved_warning_one", 1); }
fn on_saved_warning_two(ctx)   { ctx.flags.increment("saved_warning_two", 1); }
fn on_lost_warning_one(ctx)    { ctx.flags.increment("lost_warning_one", 1); }
fn on_lost_warning_two(ctx)    { ctx.flags.increment("lost_warning_two", 1); }
fn on_lost_warning_three(ctx)  { ctx.flags.increment("lost_warning_three", 1); }

// THE REACTION, and the whole of claim 3. On the THIRD warning the saved side
// schedules a repair four seconds out — the window a crew has to react in. If the
// final window is ever tuned shorter than four seconds, the head falls first and
// the assertion below it fails. This is the `repair_infrastructure` re-expression
// of the retired world's `stabilise`, on the same four-second clock.
fn on_saved_warning_three(ctx) {
    ctx.flags.increment("saved_warning_three", 1);
    ctx.schedule.after(4, |ctx| {
        ctx.effects.repair_infrastructure("world.probe_collapse.entity.hook_saved.name", 26);
    });
    ctx.flags.increment("saved_op_started", 1);
}

// The save landing, read off the top rung coming back up. `probe_saved_held` is
// what takes this head off the strain beat, so the two heads part company here.
fn on_saved_stands_down(ctx) {
    ctx.flags.probe_saved_held = 1;
    ctx.effects.complete_objective("obj-probe-saved");
    ctx.flags.increment("saved_stood_down", 1);
}

// Registered for symmetry and expected NEVER TO FIRE.
fn on_lost_stands_down(ctx) {
    ctx.flags.increment("lost_stood_down", 1);
}

// The floor on the saved side: registered, and expected never to fire either.
fn on_saved_gives_way(ctx) {
    ctx.flags.increment("saved_floor_crossed", 1);
    ctx.effects.destroy_entity("world.probe_collapse.entity.hook_saved.name");
}

// THE FLOOR, and claim 2. One call; everything else hangs off the removal.
fn on_lost_gives_way(ctx) {
    ctx.flags.increment("lost_floor_crossed", 1);
    ctx.effects.destroy_entity("world.probe_collapse.entity.hook_lost.name");
}

fn on_lost_head_gone(ctx) {
    ctx.flags.probe_lost_gone = 1;
    // The berths went with the head.
    ctx.flags["probe_lost_berths"] = 0;
    ctx.flags.increment("lost_head_gone", 1);
    if ctx.deadlines.state("probe_projection_due") == "pending" {
        ctx.deadlines.cancel("probe_projection_due");
    }
    ctx.effects.fail_objective("obj-probe-lost");
    // The branch. Two seconds out, so the craft reads as coming out of the wreck.
    ctx.schedule.after(2, |ctx| { on_survivors(ctx); });
}

// Expected never to fire: the collapse cancels this deadline a second before it
// is due.
fn on_projection_due(ctx) {
    ctx.flags.increment("projection_fired", 1);
}

// The epilogue, and claim 4. One craft, spawned with `overrides` because it does
// not exist until the head comes apart, carrying its own threshold flag.
fn on_survivors(ctx) {
    ctx.effects.spawn_entity(#{
        template_path: "assets/entities/ship_civilian_hauler.toml",
        name: "world.probe_collapse.entity.survivor.name",
        anchor: "probe_debris",
        groups: ["probe_survivors"],
        overrides: #{
            infrastructure: #{
                condition: 20,
                hull_damage_share: 0,
                threshold: [ #{ flag: "probe_survivor_secured", fails_below: flt("0.5") } ],
            },
        },
    });
    ctx.effects.add_objective(#{
        id: "obj-probe-survivors",
        text: "world.probe_collapse.objective.survivors.text",
        mandatory: true,
    });
    ctx.flags.increment("epilogue_open", 1);
    // Two seconds later the rescue begins and pays out three seconds after that —
    // the `repair_infrastructure` re-expression of the retired world's `tow`, on
    // the same clock. Deferring the spawn's read into `name_to_uuid` too.
    ctx.schedule.after(2, |ctx| {
        ctx.flags.increment("rescue_started", 1);
        ctx.schedule.after(3, |ctx| {
            ctx.effects.repair_infrastructure("world.probe_collapse.entity.survivor.name", 45);
        });
    });
    // The epilogue's own clock, measured from the collapse: ten seconds.
    ctx.schedule.after(10, |ctx| { on_epilogue_resolves(ctx); });
}

fn on_survivor_recovered(ctx) {
    ctx.flags.probe_survivor_safe = 1;
    ctx.flags.increment("survivor_recovered", 1);
}

fn on_epilogue_resolves(ctx) {
    if ctx.flags.probe_survivor_safe > 0 {
        ctx.effects.complete_objective("obj-probe-survivors");
    } else {
        ctx.effects.fail_objective("obj-probe-survivors");
        ctx.effects.destroy_entity("world.probe_collapse.entity.survivor.name");
    }
    // Nothing left to strain: the saved head is off the beat and the lost one is
    // gone. Stopping the chain keeps the run from carrying a callback nobody
    // is watching.
    ctx.flags.probe_stopped = 1;
    ctx.flags.increment("epilogue_resolved", 1);
}

on_world_loaded("on_arrival");

fn on_arrival(ctx) {
    ctx.effects.add_objective(#{
        id: "obj-probe-saved",
        text: "world.probe_collapse.objective.saved.text",
        mandatory: true,
        targets: ["world.probe_collapse.entity.hook_saved.name"],
    });
    ctx.effects.add_objective(#{
        id: "obj-probe-lost",
        text: "world.probe_collapse.objective.lost.text",
        mandatory: true,
        targets: ["world.probe_collapse.entity.hook_lost.name"],
    });
}
"""

base_files.assets/worlds/probe_commitments.toml:
# Probe world for issue #1029 — the commitments ledger with a LIVE consumer.
#
# A player Alliance destroyer (AI-backfilled in a headless run) sits alone; no
# combat is involved on purpose. This is a deterministic tripwire for the whole
# commitments path — `ctx.commitments.record` → a dialogue node fn GATING an
# option on `ctx.commitments.state` → `keep`/`break_promise` → the campaign flag
# → an `on_flag_set` trigger reacting to it.
#
# THE LIVE CONSUMER, which is what this issue turns on: `committee_calls` is a
# real scripted dialogue node fn, opened through the real
# `ctx.effects.open_comms` pipeline, and the number of options it offers is a
# function of the ledger. It is opened TWICE against the same fn — once while
# `safe_passage` is still owed, once after it has been kept — so the probe
# proves the gate closes as well as opens, from one authored node.
#
# The authored timeline, in mission seconds:
#
#   t=2   `give_word` records two promises to the same party: `safe_passage`
#         and `surface_records`. It reads a third, never-made id back as
#         "unknown" — the answer that is NOT "broken", and the guard an author
#         uses against recording the same promise twice.
#   t=4   `open_committee_channel` opens a thread on `committee_calls`. The
#         promise is OPEN, so the node offers TWO responses: the stall, and the
#         one that exists only because the captain gave their word.
#   t=6   `honour` keeps `safe_passage`. That writes `commitment.safe_passage.kept`
#         as an ordinary world flag, which fires...
#   t=6+  ...`on_flag_set("commitment.safe_passage.kept", "word_kept")`, one tick
#         later, through the trigger pipeline that already existed. THIS is the
#         "consequences beyond the scene it was made in" half: nothing in the
#         ledger knows this trigger exists.
#   t=10  The `records_deadline` deadline fires. Its handler finds
#         `surface_records` still open and BREAKS it — the composition decision
#         made visible. The ledger carries no timer of its own; a promise-by-time
#         is a `[[deadline]]` whose handler settles it.
#   t=12  `open_committee_channel_again` opens the SAME node fn. `safe_passage`
#         now reads "kept", so the gated option is gone and the node offers ONE.
#
# Every handler increments a counter flag, so the headless test reads what
# happened out of the flag store, and asserts the option counts against the
# LIVE `CommsRuntime::active_dialogues` rather than against what script says it
# offered.
#
# BASELINE (this world is new in #1029, so this is its first recorded digest):
# `--seed 42 --ticks 900` gives final digest 0xc419b89426b6013c
# (14130528252295774524). Measured on a clean tree at the commit that added this
# line. It is a NEW number, not a preserved one — nothing to compare it against
# yet — so it is written down here to be the thing a later change is A/B'd
# against, the way the shipped worlds' digests already are.
#
# It is also, deliberately, the SAME number probe_deadlines.toml records, and
# that is worth reading rather than glossing over. The two worlds differ only in
# scenario-script state — deadlines there, commitments here — and neither is
# folded into `state_digest`; they place the same hull at the same origin under
# the same master seed. So the digests agreeing is the "authoritative but not
# folded" decision showing its work. If a later change makes these two numbers
# diverge, something started folding scenario state, and that is the question to
# ask before re-blessing either line.
#
# THE PREDICTION FIRED, on this branch. Issue #1086's
# `sim_digest::fold_scenario_records` walks `WorldContentRuntime::deadlines` and
# `::commitments` as separate named records, each folding its own authored
# content — a deadline table and a commitments ledger with different contents
# no longer produce the same residue. probe_deadlines.toml and this file are
# RECORDED PRE-#1086, AND NO LONGER REPRODUCIBLE, and no longer expected to
# agree: something started folding scenario state, and this is it. Re-measure
# each world independently before treating either number as a baseline again.

[global]
seed = 1029
ai_helm_tick_hz = 30.0

[player_spawn]
position = [0.0, 0.0, 0.0]

# Player ship — spawned by spawn_game_start_entities when the game starts.
[[entity]]
template_path = "assets/entities/alliance_destroyer.toml"
id = "player-ship"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

# ── The deadline a promise is settled against ────────────────────────────────
# There is deliberately no `[[commitment]]` block anywhere in this file: a
# promise is a RUNTIME artifact, made in the beat where the captain gives their
# word, and a world file cannot declare one because whether it exists at all
# depends on what the player chose to say. What a world file CAN declare is the
# clock the promise is tested against — and that is an ordinary deadline.
[[deadline]]
id = "records_deadline"
label = "world.probe_commitments.deadline.records_deadline.label"
due_secs = 10
visible = true

[script]
setup = """
on_timer(2, "give_word");
on_timer(4, "open_committee_channel");
on_timer(6, "honour");
on_timer(12, "open_committee_channel_again");

on_deadline("records_deadline", "on_records_deadline");

// The campaign-flag chain. Nothing in the ledger knows these exist — they are
// ordinary flag triggers, watching ordinary world flags.
on_flag_set("commitment.safe_passage.kept", "word_kept");
on_flag_set("commitment.surface_records.broken", "word_broken");

// The negotiation beat: giving your word. In a shipped mission this body is a
// dialogue `on_pick`; here a timer stands in for the player's finger so the run
// is deterministic. The vocabulary is identical either way — the live
// player-driven loop is covered by the comms tests in src/comms/scripted.rs.
fn give_word(ctx) {
    ctx.commitments.record(#{
        id:            "safe_passage",
        made_to:       "skyway_strike_committee",
        terms:         "world.probe_commitments.commitment.safe_passage.terms",
        resolves_when: "world.probe_commitments.commitment.safe_passage.resolves",
    });
    ctx.commitments.record(#{
        id:            "surface_records",
        made_to:       "skyway_strike_committee",
        terms:         "world.probe_commitments.commitment.surface_records.terms",
        resolves_when: "world.probe_commitments.commitment.surface_records.resolves",
    });
    // Read-after-write within the one call: a promise made earlier in this
    // handler is already on the books for the rest of it.
    if ctx.commitments.state("safe_passage") == "open" {
        ctx.flags.increment("passage_reads_open", 1);
    }
    // The fourth answer. A promise that was never made is "unknown" — never
    // "broken" — and this is the guard against recording a duplicate.
    if ctx.commitments.state("never_promised") == "unknown" {
        ctx.flags.increment("unmade_reads_unknown", 1);
    }
}

// THE LIVE CONSUMER. One node fn, opened twice; its option list is a function
// of the ledger. Gating is ordinary control flow — there is no `when:` field on
// a response, and this slice does not add one.
fn committee_calls(ctx) {
    let responses = [
        #{ text: "world.probe_commitments.comms.stall", on_pick: "on_stall" },
    ];
    if ctx.commitments.state("safe_passage") == "open" {
        responses.push(#{
            text: "world.probe_commitments.comms.honour_word",
            on_pick: "on_honour_word",
        });
    }
    #{ message: "world.probe_commitments.comms.committee_calls", responses: responses }
}

fn on_stall(ctx) { }

fn on_honour_word(ctx) {
    ctx.commitments.keep("safe_passage");
}

fn open_committee_channel(ctx) {
    ctx.effects.open_comms(#{ from: "_self", node_fn: "committee_calls" });
}

fn open_committee_channel_again(ctx) {
    ctx.effects.open_comms(#{ from: "_self", node_fn: "committee_calls" });
}

// Keeping the promise. Writes `commitment.safe_passage.kept` as an ordinary
// world flag, on the same ordered effect buffer this handler's own flag writes
// use.
fn honour(ctx) {
    ctx.commitments.keep("safe_passage");
    // Read-after-write again: the rest of this call sees a settled promise.
    if ctx.commitments.state("safe_passage") == "kept" {
        ctx.flags.increment("passage_reads_kept", 1);
    }
}

// The composition decision, made visible: the ledger carries no timer, so a
// promise-by-time is a `[[deadline]]` whose handler settles it.
fn on_records_deadline(ctx) {
    if ctx.commitments.state("surface_records") == "open" {
        ctx.commitments.break_promise("surface_records");
        ctx.flags.increment("records_broken_by_deadline", 1);
    }
}

// The chain. These fire from the trigger pipeline on the tick AFTER the flag
// transition, which is why they can read the settled ledger back.
fn word_kept(ctx) {
    ctx.flags.increment("kept_flag_chained", 1);
    if ctx.commitments.state("safe_passage") == "kept" {
        ctx.flags.increment("chain_reads_kept", 1);
    }
}

fn word_broken(ctx) {
    ctx.flags.increment("broken_flag_chained", 1);
    // The distinction the whole slice turns on: a broken promise is not an
    // unresolved one, and the chained handler can tell.
    if ctx.commitments.state("surface_records") == "broken" {
        ctx.flags.increment("chain_reads_broken", 1);
    }
}
"""

base_files.assets/worlds/probe_corroborate.toml:
# Probe world for issue #1039 — a witness whose channel opens on two gates, with
# every corner of the matrix authored at once so no single run can be mistaken
# for the mechanism.
#
# The slice's claim is that corroboration is CONDITIONAL, on two separate things
# the crew did, and that a run in which it happens and a run in which it does not
# differ only in those two things. A world that opened the channel on a timer
# would look identical from the outside on one playthrough — so this world stands
# five sites side by side, authored line for line the same, and moves only the
# gates.
#
#   both      the record on the sheet, the dispute settled by NEGOTIATION
#             -> the witness calls, the account is filed, the confrontation
#                unlocks. The whole beat.
#   late      the same two facts, ARRIVING IN THE OTHER ORDER: settled first,
#             the record filed two seconds later
#             -> nothing at the settlement, and the witness calls when the
#                record lands. The gate is a pair of conditions, not a sequence.
#   forced    the record on the sheet, and the dispute ended the OTHER way —
#             the picket cleared rather than talked down
#             -> silence, for the whole run. The gate under test is HOW it ended.
#   unheard   settled by negotiation, and nobody ever read the rung
#             -> silence. The gate under test is having something to ask about.
#   quiet     neither. The control.
#
# Read them in pairs and each gate isolates. Both against Forced is the
# SETTLEMENT: identical records, identical witness, identical everything, and the
# only difference is which flag the dispute ended on. Both against Unheard is the
# EVIDENCE: identical settlements, and the only difference is whether anything
# was ever filed about the rung. Both against Late is the ORDER, and Late is the
# corner a scripted reveal could not produce — its witness calls on a tick
# nothing was settled and nobody chose anything, because the OTHER half of the
# pair arrived.
#
# ── What the sites are made of ──────────────────────────────────────────────
#
# Each site is a RUNG (the dossier subject — what the evidence is about) and a
# WITNESS (a hailable hull — who says it). They are separate entities because
# they are separate things, and `probe_evidence.toml` states the rule this world
# leans on entirely: a finding is filed under what it is ABOUT, not under who
# said it. So every append below lands on a rung, never on the person, and the
# rung's fact sheet is where the two provenances end up side by side.
#
# The five rungs carry no thresholds and no capacities. Nothing here is a
# condition question — #1038's probe is where a structure's own numbers decide
# anything — and a shared capacity id across five instances would be five rungs
# publishing one counter between them.
#
# ── The clock, and why it is a clock ────────────────────────────────────────
#
#   t=0   `file_the_records_that_were_read` files the RECORDS finding onto the
#         rungs whose crews did the reading: `both` and `forced`. Not onto
#         `late` (its crew read it later), and not onto `unheard` or `quiet`
#         (their crews never did).
#   t=2   `settle_the_disputes` writes each site's gate flags. Nothing is asked
#         on this tick: a script call reads the flag store as it stood when the
#         call started, so a sweep in the same handler would be asking about a
#         world its own writes had not reached yet.
#   t=3   `ask_every_site` — the first sweep. `both` opens. `late` does not.
#   t=4   `the_late_record_lands` files `late`'s finding, and nothing else moves.
#         No settlement, no pick, no timer that knows what a witness is.
#   t=5   `ask_every_site` again. `late` opens, on a tick whose only new fact is
#         a document. THAT is the either-order claim.
#   t=8   `ask_every_site` a third time, and then `unlock_every_site`. The three
#         silent sites are asked with every flag they will ever have, so their
#         silence is a refusal rather than a race; and the unlock is read off the
#         fact sheets a beat after the last account was filed, which is the only
#         honest moment to read it (an append is applied by the applier, so a
#         handler cannot see its own).
#
# ── Who answers ─────────────────────────────────────────────────────────────
#
# The crew's Comms officer is AI-backfilled and answers an open thread with its
# FIRST response, which is `probe_evidence.toml`'s rule and is RESTATED on the
# player hull below. The threads that open are therefore answered through the
# ordinary admitted `RespondToMessage` path, and the `on_pick` that files the
# account runs as a genuine dialogue pick rather than as a timer standing in for
# one. It is also why the scenario puts its own ask at index 0 — see
# `falling_skyway.toml`.
#
# [ai] "RESTATED", not "supplied". This paragraph used to say the rule was
# authored below "because the stock destroyer declares none", and that was
# wrong: the destroyer COMPOSES that exact rule from
# `fragments/ai/fleet_baseline.toml`, as every Alliance hull does.
# `probe_evidence.toml`'s header carries the full account — including why the
# override only reached the spawned ship at all once the player-ship override
# defect found in #1036 was fixed — and the same keep-or-delete question
# applies to this copy of it.
#
# BASELINE (headless, `--seed 42 --ticks 900 --digest-every 0`, no `--ship`
# override — the invocation `probe_scandiff.toml` and `probe_scan.toml` record):
# final digest 0x567af1547ec4e45f (6231558379626882143). A NEW number — nothing
# to compare it against yet — so it is written down to be the thing a later
# change is A/B'd against, the way the shipped worlds' digests already are. Tick
# 0 is 9061975724796068249 (0x7dc29ae8c7aec199).
#
# The anchors were measured on the same clean tree and are UNMOVED: combat_test
# 14942520827746055774, patrol 11531679067393217131, probe_evidence
# 5001167740764356580, probe_scan 7851858877582205234, probe_strike
# (--ticks 1800) 535291289754814419, probe_storm (--ticks 6480)
# 11434311098359716284, and probe_scandiff 2488189563210329022.
# `falling_skyway` DID move, and its own header carries the A/B that attributes
# the move to one authored entity rather than to anything this world does.
#
# RECORDED PRE-#1086, AND NO LONGER REPRODUCIBLE. Issue #1086 widened the
# authoritative digest over the scenario's own state — the flag stores, the
# trigger latches, the named records (deadlines, commitments, evidence,
# workforce) and the whole of `CommsState` — so every gate this world's five
# sites turn on (the RECORDS/settlement flags, the evidence appended to each
# rung, and the witness threads themselves) is now walked by
# `sim_digest::fold_scenario_records` / `fold_comms_scope` rather than merely
# snapshotted. Every number above, this world's own included, predates that
# fold and does not reproduce on a clean tree. Re-measure before treating any
# of it as a baseline again.
#
# STILL 0x567af1547ec4e45f after the player-ship override fix (the defect found
# in #1036), for `probe_evidence.toml`'s reason: the fix makes the override
# below reach the spawned hull for the first time, and what it lands is the rule
# `fragments/ai/fleet_baseline.toml` was already giving that hull.
#
# What is IN that digest is the entity population and eleven hulls' transforms.
# What is NOT in it is every single thing this world exists to exercise: an
# evidence entry, a flag-store counter, a comms thread and an objective are all
# authoritative-but-unfolded, in the same bucket as the deadline table and the
# commitments ledger. If a later change moves this number without moving a hull
# or the population, something started folding scenario state, and that is the
# question to ask before re-blessing this line.

[global]
seed = 1039
ai_helm_tick_hz = 30.0

[player_spawn]
position = [0.0, 0.0, 0.0]

# The crew's hull. The Comms response policy below RESTATES what every Alliance
# hull already composes from `fragments/ai/fleet_baseline.toml`; it is authored
# here so the rule the two threads depend on belongs to the world rather than to
# whichever hull the lobby picks — see the header.
[[entity]]
template_path = "assets/entities/alliance_destroyer.toml"
id = "player-ship"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

[[entity.overrides.comms_console.ai.rule]]
priority = 0
channel = "comms_respond"
when = "fact(comms_available) > 0 and fact(sender_in_range) > 0"
verb = "respond_to_message"
response_index = 0

# ── The five rungs ───────────────────────────────────────────────────────────
#
# The subjects. Authored identically: same template, same absence of thresholds
# and capacities, nothing on any of them that a script branches on. What lands on
# each one's sheet is decided entirely by the gates, which is the point.

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
id = "rung_both"
name = "world.probe_corroborate.entity.rung_both.name"
transform = { position = [600.0, 0.0, 0.0] }
[entity.overrides.infrastructure]
capacity = []

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
id = "rung_late"
name = "world.probe_corroborate.entity.rung_late.name"
transform = { position = [1200.0, 0.0, 0.0] }
[entity.overrides.infrastructure]
capacity = []

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
id = "rung_forced"
name = "world.probe_corroborate.entity.rung_forced.name"
transform = { position = [1800.0, 0.0, 0.0] }
[entity.overrides.infrastructure]
capacity = []

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
id = "rung_unheard"
name = "world.probe_corroborate.entity.rung_unheard.name"
transform = { position = [2400.0, 0.0, 0.0] }
[entity.overrides.infrastructure]
capacity = []

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
id = "rung_quiet"
name = "world.probe_corroborate.entity.rung_quiet.name"
transform = { position = [3000.0, 0.0, 0.0] }
[entity.overrides.infrastructure]
capacity = []

# ── The five witnesses ───────────────────────────────────────────────────────
#
# Hailable hulls, all of them well inside the destroyer's authored 1000-unit
# comms range, because a thread that failed to open for want of range would be
# indistinguishable from a gate refusing it. Five, not one, so "this site's
# witness never called" is a statement about a real party rather than about a
# shared channel being busy.

[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "witness_both"
name = "world.probe_corroborate.entity.witness_both.name"
transform = { position = [300.0, 0.0, -300.0] }
overrides = { comms = { hailable = true } }

[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "witness_late"
name = "world.probe_corroborate.entity.witness_late.name"
transform = { position = [300.0, 0.0, 300.0] }
overrides = { comms = { hailable = true } }

[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "witness_forced"
name = "world.probe_corroborate.entity.witness_forced.name"
transform = { position = [450.0, 0.0, -150.0] }
overrides = { comms = { hailable = true } }

[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "witness_unheard"
name = "world.probe_corroborate.entity.witness_unheard.name"
transform = { position = [450.0, 0.0, 150.0] }
overrides = { comms = { hailable = true } }

[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "witness_quiet"
name = "world.probe_corroborate.entity.witness_quiet.name"
transform = { position = [150.0, 0.0, 0.0] }
overrides = { comms = { hailable = true } }

[script]
setup = """
on_world_loaded("file_the_records_that_were_read");
on_timer(2, "settle_the_disputes");
on_timer(3, "ask_every_site");
on_timer(4, "the_late_record_lands");
on_timer(5, "ask_every_site_again");
on_timer(8, "the_last_word");

// ── t=0: what each crew had read by the time the mission started ────────────
// RECORDS provenance, because it is a document comparison. Two sites have it,
// one gets it later, two never do — and that is the only difference between the
// five fact sheets when the clock starts.
fn file_the_records_that_were_read(ctx) {
    ctx.dossier.append(#{
        subject:    "world.probe_corroborate.entity.rung_both.name",
        text:       "world.probe_corroborate.evidence.record_both",
        provenance: "records",
    });
    ctx.dossier.append(#{
        subject:    "world.probe_corroborate.entity.rung_forced.name",
        text:       "world.probe_corroborate.evidence.record_forced",
        provenance: "records",
    });
    ctx.flags.records_filed = 1;
}

// ── t=2: how each dispute ended ─────────────────────────────────────────────
// `forced` gets `settled_forced` as well as `forced_forced`, so it is not the
// site where nothing happened — its dispute ended too. What it does not have is
// the one flag the gate actually reads.
fn settle_the_disputes(ctx) {
    ctx.flags.negotiated_both = 1;
    ctx.flags.negotiated_late = 1;
    ctx.flags.negotiated_unheard = 1;

    ctx.flags.forced_forced = 1;
    ctx.flags.settled_forced = 1;

    ctx.flags.ground_set = 1;
}

// ── t=4: one document, arriving late and alone ──────────────────────────────
// Nothing else moves on this tick. No settlement, no pick, and no handler that
// knows a witness exists.
fn the_late_record_lands(ctx) {
    ctx.dossier.append(#{
        subject:    "world.probe_corroborate.entity.rung_late.name",
        text:       "world.probe_corroborate.evidence.record_late",
        provenance: "records",
    });
    ctx.flags.late_filed = 1;
}

// ── The gate, once, for every site ──────────────────────────────────────────
//
// TWO READS OF THE WORLD AND NO MEMORY OF ITS OWN, exactly as #1038's comparison
// is. It does not know which site it is looking at beyond the names it was
// handed; it does not know how anything got into the flag store or onto a sheet.
// Re-author `settle_the_disputes` to negotiate the forced site and that site
// opens, with no line of copy edited and no handler touched.
fn open_if_the_ground_holds(ctx, called, negotiated, forced, record, witness, node) {
    if ctx.flags[called] > 0 { return; }
    if ctx.flags[forced] > 0 { return; }
    if ctx.flags[negotiated] == 0 { return; }
    if !ctx.dossier.holds(#{ text: record }) { return; }

    ctx.flags[called] = 1;
    ctx.effects.open_comms(#{ from: witness, node_fn: node, urgent: true });
}

fn ask_every_site(ctx) {
    open_if_the_ground_holds(ctx, "called_both", "negotiated_both", "forced_both",
        "world.probe_corroborate.evidence.record_both",
        "world.probe_corroborate.entity.witness_both.name", "both_hails");
    open_if_the_ground_holds(ctx, "called_late", "negotiated_late", "forced_late",
        "world.probe_corroborate.evidence.record_late",
        "world.probe_corroborate.entity.witness_late.name", "late_hails");
    open_if_the_ground_holds(ctx, "called_forced", "negotiated_forced", "forced_forced",
        "world.probe_corroborate.evidence.record_forced",
        "world.probe_corroborate.entity.witness_forced.name", "forced_hails");
    open_if_the_ground_holds(ctx, "called_unheard", "negotiated_unheard", "forced_unheard",
        "world.probe_corroborate.evidence.record_unheard",
        "world.probe_corroborate.entity.witness_unheard.name", "unheard_hails");
    open_if_the_ground_holds(ctx, "called_quiet", "negotiated_quiet", "forced_quiet",
        "world.probe_corroborate.evidence.record_quiet",
        "world.probe_corroborate.entity.witness_quiet.name", "quiet_hails");
    ctx.flags.increment("swept", 1);
}

fn ask_every_site_again(ctx) { ask_every_site(ctx) }

// The last sweep, and then the read. Asking a third time is what makes the three
// silences a REFUSAL rather than a race: every flag those sites will ever have
// is set by t=2, so a site that has not called by t=8 was never going to.
fn the_last_word(ctx) {
    ask_every_site(ctx);
    unlock_every_site(ctx);
}

// ── The five witnesses, authored identically ────────────────────────────────
//
// All five node functions exist and all five say the same thing. Three of them
// are never called, which is the control: the difference between the sites is
// not that some of them have a witness with something to say.

fn both_hails(ctx)    { #{ message: "world.probe_corroborate.comms.witness_hails",
    responses: [#{ text: "world.probe_corroborate.comms.witness_ask", on_pick: "on_ask_both" }] } }
fn late_hails(ctx)    { #{ message: "world.probe_corroborate.comms.witness_hails",
    responses: [#{ text: "world.probe_corroborate.comms.witness_ask", on_pick: "on_ask_late" }] } }
fn forced_hails(ctx)  { #{ message: "world.probe_corroborate.comms.witness_hails",
    responses: [#{ text: "world.probe_corroborate.comms.witness_ask", on_pick: "on_ask_forced" }] } }
fn unheard_hails(ctx) { #{ message: "world.probe_corroborate.comms.witness_hails",
    responses: [#{ text: "world.probe_corroborate.comms.witness_ask", on_pick: "on_ask_unheard" }] } }
fn quiet_hails(ctx)   { #{ message: "world.probe_corroborate.comms.witness_hails",
    responses: [#{ text: "world.probe_corroborate.comms.witness_ask", on_pick: "on_ask_quiet" }] } }

// The account. DIALOGUE provenance, onto the RUNG — somebody's word about a
// structure, filed under the structure, beside the records comparison that is
// already there. The flag is written after the append for the reason
// `falling_skyway.toml` gives at its own call site: a call's commands are
// applied in the order the script wrote them.
fn testify(ctx, subject, account, corroborated) {
    ctx.dossier.append(#{
        subject:    subject,
        text:       account,
        provenance: "dialogue",
    });
    ctx.flags[corroborated] = 1;
    #{ message: "world.probe_corroborate.comms.witness_account", responses: [] }
}

fn on_ask_both(ctx) {
    testify(ctx, "world.probe_corroborate.entity.rung_both.name",
        "world.probe_corroborate.evidence.account_both", "corroborated_both")
}
fn on_ask_late(ctx) {
    testify(ctx, "world.probe_corroborate.entity.rung_late.name",
        "world.probe_corroborate.evidence.account_late", "corroborated_late")
}
fn on_ask_forced(ctx) {
    testify(ctx, "world.probe_corroborate.entity.rung_forced.name",
        "world.probe_corroborate.evidence.account_forced", "corroborated_forced")
}
fn on_ask_unheard(ctx) {
    testify(ctx, "world.probe_corroborate.entity.rung_unheard.name",
        "world.probe_corroborate.evidence.account_unheard", "corroborated_unheard")
}
fn on_ask_quiet(ctx) {
    testify(ctx, "world.probe_corroborate.entity.rung_quiet.name",
        "world.probe_corroborate.evidence.account_quiet", "corroborated_quiet")
}

// ── The unlock: a read of two fact sheets, not a second name for a pick ─────
//
// Both entries, each narrowed to its own provenance. The three silent sites fail
// it in two different ways and the distinction is worth having: `forced` holds a
// records comparison and no word from anybody, while `unheard` and `quiet` hold
// neither. Nothing here knows which site opened a channel.
fn unlock_if_both_halves(ctx, unlocked, record, account) {
    if ctx.flags[unlocked] > 0 { return; }
    if !ctx.dossier.holds(#{ text: record, provenance: "records" }) { return; }
    if !ctx.dossier.holds(#{ text: account, provenance: "dialogue" }) { return; }
    ctx.flags[unlocked] = 1;
}

fn unlock_every_site(ctx) {
    unlock_if_both_halves(ctx, "unlocked_both",
        "world.probe_corroborate.evidence.record_both",
        "world.probe_corroborate.evidence.account_both");
    unlock_if_both_halves(ctx, "unlocked_late",
        "world.probe_corroborate.evidence.record_late",
        "world.probe_corroborate.evidence.account_late");
    unlock_if_both_halves(ctx, "unlocked_forced",
        "world.probe_corroborate.evidence.record_forced",
        "world.probe_corroborate.evidence.account_forced");
    unlock_if_both_halves(ctx, "unlocked_unheard",
        "world.probe_corroborate.evidence.record_unheard",
        "world.probe_corroborate.evidence.account_unheard");
    unlock_if_both_halves(ctx, "unlocked_quiet",
        "world.probe_corroborate.evidence.record_quiet",
        "world.probe_corroborate.evidence.account_quiet");
    ctx.flags.increment("unlocks_read", 1);
}
"""

base_files.assets/worlds/probe_despawn.toml:
# Probe world for issue #838 — regression harness for the "destroyed entity
# emits EntityDespawned twice" bug.
#
# Two world-spawned hulls fight far from the player: a strong Harrow battleship
# (the aggressor) and a weaker Alliance destroyer (the victim), placed a few
# units apart and made mutually hostile. The battleship kills the destroyer,
# producing exactly one destroyed entity. The bug emitted `EntityDespawned`
# twice for that one kill — once eagerly at the weapon kill site and again from
# the reconcile sweep, which the kill site never told about the despawn. With
# the fix the kill site forgets the uuid from `TrackedEntities`, so the run
# emits exactly one `EntityDespawned`.
#
# The player sits at the origin, ~900 units away and OUTSIDE its own high-LOD
# bubble (the default 600 units, 720 with hysteresis — see `LodBubble`), so the
# duel runs in the cheap low-LOD path: the aggressor kills the victim with a
# single beam and nothing escalates to a torpedo exchange. That single-weapon
# kill is the point — this test guards the #838 RECONCILE double-emit (one kill,
# one `EntityDespawned`). Pulling the duel INTO the bubble would promote both
# hulls to full fidelity, where they trade torpedoes and two kill sites race to
# despawn one victim — a separate, pre-existing multi-weapon double-emit that
# does not belong to this fixture.

[global]
seed = 8380
ai_helm_tick_hz = 30.0

[player_spawn]
position = [0.0, 0.0, 0.0]

[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "player-ship"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

[script]
setup = """
// Make Harrow and Alliance mutually hostile before the hulls spawn.
on_world_loaded("on_load");
// Spawn the two duelling hulls at t=0.
on_timer(0, "on_start");

fn on_load(ctx) {
    ctx.effects.add_faction_enemy("Harrow", "Alliance");
    ctx.effects.add_faction_enemy("Alliance", "Harrow");
}

fn on_start(ctx) {
    // The aggressor: a Harrow-flagged battleship with a standing Destroy doctrine.
    ctx.effects.spawn_entity(#{
        template_path: "assets/entities/alliance_battleship.toml",
        name: "aggressor",
        position: [900, 0, 0],
        overrides: #{ faction: "cccccccc-3333-4333-8333-cccccccccccc", behaviour: #{ doctrine: [
            #{ id: "kill", directive_kind: "Destroy",
               base_priority: 80, target_speed: flt("0.9"), maintain_range: 20 },
        ] } }
    });

    // The victim: a lightly-built Alliance courier placed right next to the
    // aggressor. It also has a Destroy doctrine so both sides trade fire, but it is
    // heavily outgunned by the battleship and is the one that dies.
    ctx.effects.spawn_entity(#{
        template_path: "assets/entities/alliance_courier.toml",
        name: "victim",
        position: [914, 0, 0],
        overrides: #{ behaviour: #{ doctrine: [
            #{ id: "kill", directive_kind: "Destroy",
               base_priority: 80, target_speed: flt("0.9"), maintain_range: 12 },
        ] } }
    });
}
"""

base_files.assets/worlds/probe_destroy_chain.toml:
# Probe world for issue #1033 — scripted entity REMOVAL, end to end.
#
# This is the minimal, operations-free successor to the retired `probe_destroy`
# world (#1164, S11a): the per-system probes now cover the operation verbs, so
# this world keeps ONLY the scripted-removal mechanic #1033 owns and drives it
# with world-scripting effects alone — no `[operations]` capability anywhere.
#
# A scripted destruction is INDISTINGUISHABLE from a combat kill downstream: it
# chains the same `WorldEvent::Destroyed`, so the same `on_destroyed` and
# `on_all_destroyed` triggers fire off it, and it leaves the same nothing behind
# in a snapshot.
#
# The authored timeline, in mission seconds:
#
#   t=0    `on_start` spawns TWO storm bands into the `storm_band` group and
#          posts both objectives. The bands are spawned rather than authored as
#          `[[entity]]` blocks because group membership only registers through
#          `SpawnEntity` dispatch — an `on_all_destroyed` group has no other way
#          to learn who is in it.
#   t=5    the `skyhook_collapse` deadline fires and the script destroys the
#          skyhook. `on_skyhook_lost` (a chained `on_destroyed`) FAILS its
#          objective off the same Destroyed event, in the same tick.
#   t=6    `on_sweep` schedules the first band's retirement two seconds out,
#          through `ctx.schedule.in_seconds(2).destroy_entity(…)`. The DEFERRED
#          form, deliberately: it is the same `TriggerAction` on the same queue.
#   t=8    band A is retired by that deferred call. The group must stay SILENT —
#          one of two is not all of them.
#   t=10   `on_sweep_last` retires band B immediately. NOW `on_all_destroyed`
#          fires and completes the band objective.
#
# Every handler writes a counter flag, so the headless test reads fire ORDER and
# fire COUNT out of the flag store rather than out of a log line.

[global]
seed = 1033
ai_helm_tick_hz = 30.0

[player_spawn]
position = [0.0, 0.0, 0.0]

# The player ship, present because a world needs one. It does no work here.
[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "player-ship"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

# The structure that collapses on a named deadline. A plain depot; nothing
# operates on it, it is simply removed by script.
[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_destroy.entity.skyhook.name"
transform = { position = [400.0, 0.0, 0.0] }
overrides = { infrastructure = { condition = 30.0 } }

# The collapse, as a named thing in the world rather than an anonymous timer —
# the crew can watch it coming.
[[deadline]]
id = "skyhook_collapse"
label = "world.probe_destroy.deadline.skyhook_collapse.label"
due_secs = 5
visible = true

[script]
setup = """
on_timer(0, "on_start");
on_timer(6, "on_sweep");
on_timer(10, "on_sweep_last");

on_deadline("skyhook_collapse", "on_collapse");

// The two chained triggers. Neither is armed by anything this world shoots at;
// only a scripted destruction can make either fire.
on_destroyed("world.probe_destroy.entity.skyhook.name", "on_skyhook_lost");
on_all_destroyed("storm_band", "on_band_cleared");

fn on_start(ctx) {
    // Two bands of the same storm, spawned into one group so retiring the
    // storm means retiring all of it.
    ctx.effects.spawn_entity(#{
        template_path: "assets/entities/region_storm_band.toml",
        name: "storm_band_a",
        position: [1200, 0, 0],
        groups: ["storm_band"],
    });
    ctx.effects.spawn_entity(#{
        template_path: "assets/entities/region_storm_band.toml",
        name: "storm_band_b",
        position: [1200, 0, 900],
        groups: ["storm_band"],
    });

    ctx.effects.add_objective(#{
        id: "obj-hold-skyhook",
        text: "world.probe_destroy.objective.hold_skyhook.text",
        mandatory: true,
        targets: ["world.probe_destroy.entity.skyhook.name"],
    });
    ctx.effects.add_objective(#{
        id: "obj-clear-band",
        text: "world.probe_destroy.objective.clear_band.text",
    });
}

// The collapse itself: one call, and everything below follows from it.
fn on_collapse(ctx) {
    ctx.effects.destroy_entity("world.probe_destroy.entity.skyhook.name");
    ctx.flags.increment("collapse_fired", 1);
}

// Chained off the collapse's own Destroyed event, in the same tick.
fn on_skyhook_lost(ctx) {
    ctx.effects.fail_objective("obj-hold-skyhook");
    ctx.flags.increment("skyhook_lost", 1);
}

// The DEFERRED destroy: same action, same queue, two seconds later.
fn on_sweep(ctx) {
    ctx.schedule.in_seconds(2).destroy_entity("storm_band_a");
    ctx.flags.increment("sweep_scheduled", 1);
}

fn on_sweep_last(ctx) {
    ctx.effects.destroy_entity("storm_band_b");
    ctx.flags.increment("sweep_last", 1);
}

fn on_band_cleared(ctx) {
    ctx.effects.complete_objective("obj-clear-band");
    ctx.flags.increment("band_cleared", 1);
}
"""

base_files.assets/worlds/probe_fleet_comms_choice.t:
# Probe world for issue #1343 — a weighted Backfill Comms decision, taken by a
# FLEET rather than by a single hull.
#
# `probe_fleet_duel.toml` is the class this borrows from (two `game_start` ship
# rows, a hostile close enough to engage, a short `command_delay_ticks`) and the
# one thing it adds is the reason it exists: `open_comms` conversations whose
# responses author `ai_weight` / `ai_delay_seconds`.
#
# WHY IT HAD TO BE ITS OWN WORLD. `tests/local_ship_neutrality.rs` runs a world
# twice with the `LocalShip` marker on a different fleet hull and compares the
# authoritative fold on every tick. Neither of its two existing probes contains a
# single `open_comms` call, so the comms scope of the digest was never entered
# and the guard could not see the state #1343 added to it — an unmanned Comms
# console's running weighted decisions, which `sim_digest::fold_comms_scope`
# walks. This world enters that scope, holds waits open across many ticks, and
# then resolves them.
#
# TWO EQUALLY-WEIGHTED OPTIONS, which is the shape Falling Skyway's lift band
# actually authors and the only shape that makes the comparison bite. With a pool
# of one, every hull on every host draws the same answer and the guard passes
# whatever the emission does; with a pool of two the hulls draw independently, so
# the flags an `on_pick` writes record WHICH way each corridor went. A host that
# emitted or drained only the hull it happens to project leaves the other
# corridor unanswered — and, because an admitted AI command is never logged and
# so never replicates, unanswered on that host alone: a divergence in
# `selected_response`, in the flags the `on_pick` wrote, and in the retired
# dialogue. That is exactly the bug `handle_respond_to_message`'s fleet-wide
# drain fixes, and this world is what holds it fixed.
#
# TWO CLAIMANTS, EACH REACHABLE BY EXACTLY ONE HULL, which is the geometry the
# rest of the guard rests on. Each claimant sits 40 units from its own hull and
# 360 from the other, and each authors a 200-unit comms range (the effective
# range is `min(hull 1200, claimant 200)`), so every reachability reading here is
# ASYMMETRIC: slot 1 can answer the near claimant and not the far one, slot 2 the
# other way about. That asymmetry is the whole point — it is what makes
# "reachable?" a per-hull question rather than a fleet-wide constant, so a host
# that answers it from `CommsRuntime::range_flags` (measured from `LocalShip`,
# a different hull on each host) reads BOTH conversations as its own hull sees
# them and diverges from its peer three ways at once: the injected message's
# folded `sender_in_range` stamp, whose consoles arm a wait, and whether the
# response router admits the answer. A world whose hulls sit equidistant from
# one claimant cannot see any of that, because every host computes the same
# number by accident.
#
# WHY THE ASYMMETRY IS AUTHORED IN COMMS RANGE RATHER THAN IN DISTANCE. Every
# entity here is deliberately within `DEFAULT_PLAYER_LOD_BUBBLE_RADIUS` (600) of
# BOTH hulls, so `ai::server::lod_ai_ships` — which anchors its high-fidelity
# bubble on the `LocalShip` — reaches the same verdict for every NPC on both
# hosts. Spreading the fleet out until the claimants fell outside comms range by
# DISTANCE would put them outside that bubble too, and the guard would then fail
# on an unrelated (and much older) `LocalShip` reading instead of the comms one
# it is here to make. Shrinking the claimants' authored range keeps the whole
# world inside one bubble and still splits the comms reading in two.
#
# The stand-by sits at index 0 carrying `ai_weight = 0`, because the other thing
# worth proving here is that an unmanned bridge does NOT answer with it.

[global]
seed = 1343
ai_helm_tick_hz = 30.0
# Two ticks at 60 Hz, as `probe_fleet_duel.toml` authors and for its reason: a
# probe wants the future-tick path exercised in a handful of ticks.
command_delay_ticks = 2

[player_spawn]
position = [0.0, 0.0, 0.0]

# Fleet slot 1's ship — the fleet owner's. Takes `[player_spawn]`.
[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "fleet-ship-1"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

# Fleet slot 2's ship, placed by its own transform — 400 units up the line: far
# enough that each claimant's 200-unit comms range holds one hull and not the
# other, close enough that every entity here stays inside one LOD bubble.
[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "fleet-ship-2"
transform = { position = [400.0, 0.0, 0.0] }
spawn_on = "game_start"

# The party that calls SLOT 1. A real, hailable hull rather than `_self`: the
# response router range-gates a pick against the SENDER's live range flag, so
# only a reachable sender can be answered — the same authoring rule
# `probe_evidence.toml` records. 40 units from slot 1 and 360 from slot 2, with
# an authored 200-unit comms range: exactly one console in the fleet can answer
# it.
[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "corridor_claimant"
name = "world.probe_fleet_comms_choice.entity.claimant.name"
transform = { position = [40.0, 0.0, 0.0] }
overrides = { comms = { hailable = true, range = 200.0 } }

# The party that calls SLOT 2 — the mirror image, 40 units from slot 2 and 360
# from slot 1.
[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "corridor_claimant_far"
name = "world.probe_fleet_comms_choice.entity.claimant_far.name"
transform = { position = [360.0, 0.0, 0.0] }
overrides = { comms = { hailable = true, range = 200.0 } }

[script]
setup = """
on_world_loaded("on_load");
on_timer(0, "on_spawn");
on_timer(2, "open_corridor_claims");

fn on_load(ctx) {
    ctx.effects.add_faction_enemy("Harrow", "Alliance");
    ctx.effects.add_faction_enemy("Alliance", "Harrow");
}

// The hostile, placed EQUIDISTANT from the two hulls (283 units from each) so
// the combat half of the world is symmetric and the only asymmetry in it is the
// one the comms half is testing.
fn on_spawn(ctx) {
    ctx.effects.spawn_entity(#{
        template_path: "assets/entities/alliance_cruiser.toml",
        name: "fleet_probe_hostile",
        position: [200, 0, 200],
        overrides: #{ faction: "cccccccc-3333-4333-8333-cccccccccccc" }
    });
}

// The decisions. Opened two seconds in, so the fleet is spawned and its comms
// range flags are live before the conversations exist. Two threads, one per
// claimant: each is reachable by one hull and unreachable by the other, so the
// fleet's two consoles decide about DIFFERENT conversations.
fn open_corridor_claims(ctx) {
    ctx.effects.open_comms(#{
        from: "world.probe_fleet_comms_choice.entity.claimant.name",
        node_fn: "corridor_claim",
        thread_id: "probe-fleet-corridor",
    });
    ctx.effects.open_comms(#{
        from: "world.probe_fleet_comms_choice.entity.claimant_far.name",
        node_fn: "corridor_claim",
        thread_id: "probe-fleet-corridor-far",
    });
}

// Five authored seconds of silence, then a coin-flip between the two options an
// absent officer is allowed to take. The hold is index 0 and forbidden outright;
// grant and refuse are equally weighted, the Falling Skyway lift shape. Both
// threads share the node fn — the decision is the same one twice, put to two
// different consoles.
fn corridor_claim(ctx) {
    #{
        message: "world.probe_fleet_comms_choice.comms.claim",
        responses: [
            #{ text: "world.probe_fleet_comms_choice.comms.stand_by",
               on_pick: "on_corridor_hold",
               ai_weight: 0, ai_delay_seconds: 5 },
            #{ text: "world.probe_fleet_comms_choice.comms.grant",
               on_pick: "on_corridor_grant",
               ai_weight: 1, ai_delay_seconds: 5 },
            #{ text: "world.probe_fleet_comms_choice.comms.refuse",
               on_pick: "on_corridor_refuse",
               ai_weight: 1, ai_delay_seconds: 5 },
        ],
    }
}

fn on_corridor_hold(ctx) { ctx.flags.increment("corridor_held", 1); }
fn on_corridor_grant(ctx) { ctx.flags.increment("corridor_granted", 1); }
fn on_corridor_refuse(ctx) { ctx.flags.increment("corridor_refused", 1); }
"""

base_files.assets/worlds/probe_gm_attention_fleet.t:
# Fleet-wide pending-Comms probe for #1433. One hailable speaker opens an
# ordinary WORLD-AUTHORED conversation through `ctx.effects.open_comms`, which
# — unlike a GM's own `TransmitComms` — addresses no single hull. That is the
# ordinary case for scripted scenario traffic, so the GM attention queue has to
# explain such a row without interpolating an empty ship name into the
# addressed sentence (`server.gm.attention.reason.pending_comms_fleet`).
#
# Kept apart from `probe_gm_attention.toml` deliberately: this world opens its
# conversation at t=0, and folding it into the band/ordering probe would put a
# fourth occurrence into every queue that probe's tests count.
[global]
seed = 1433
title = "world.patrol.global.title"
description = "world.patrol.global.description"
command_delay_ticks = 2

[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "fleet-ship-1"
spawn_on = "game_start"
transform = { position = [0.0, 0.0, 0.0] }

[[entity]]
template_path = "assets/entities/station_axiom.toml"
name = "world.probe_gm_attention.speaker_fleet"
transform = { position = [0.0, 0.0, -120.0] }
overrides = { comms = { hailable = true, range = 1000.0 }, tags = ["station"] }

# The speaker still owns an authored GM route, so the occurrence this world
# produces is unaddressed WITHOUT being unroutable: opening the row still lands
# on the conversation surface the scenario already authored.
[[gm_comms_route]]
id = "fleet-route"
label = "world.probe_gm_attention.route.fleet"
visibility = "selected_ships"
senders = ["world.probe_gm_attention.speaker_fleet"]

[script]
setup = """
on_timer(0, "on_start");

fn on_start(ctx) {
    ctx.effects.open_comms(#{
        from: "world.probe_gm_attention.speaker_fleet",
        node_fn: "fleet_offer"
    });
}

fn fleet_offer(ctx) {
    #{ message: "world.probe_gm_attention.offer_fleet", responses: [
        #{ text: "world.probe_gm_attention.acknowledge", on_pick: "close_offer", ai_weight: 0 }
    ] }
}

fn close_offer(ctx) { ctx.flags.increment("gm_attention_closed", 1); }
"""

base_files.assets/worlds/probe_gm_beats.toml:
# Authored eligible-beat probe for #1434 (PRD #1419 M4, story 7).
#
# Six GM-operable beats, authored the ordinary way, covering every state the
# attention queue has to read and every band an author may choose:
#
#   brief       manual, one-shot, no authored band  -> default Attention, and
#                                                      spent for ever once fired
#   recall      manual, repeatable, `urgent`        -> comes back as a FRESH
#                                                      occurrence after firing
#   storm       manual, gated by `flag(storm_ready)` -> the ready<->ineligible
#                                                      transition, both ways
#   open_gate   manual, repeatable                  -> opens that gate through
#   close_gate  manual, repeatable                     the world's own handlers
#   relief      AUTOMATIC (on_timer) + all three     -> `background`, and the
#               levers, `background`                   only beat whose moment
#                                                      would also arrive alone
#
# Nothing here needs the beats to actually fire for the queue to be right; the
# handlers only move flags, so a test can prove the projection ran without
# running any of them.
[global]
seed = 1434
title = "world.patrol.global.title"
description = "world.patrol.global.description"
command_delay_ticks = 2

[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "fleet-ship-1"
spawn_on = "game_start"
transform = { position = [0.0, 0.0, 0.0] }

[script]
setup = """
// A moment only a Game Master can cause, and only once.
gm_event("brief", "world.probe_gm_beats.beat.brief", "on_brief");

// A reusable quick tool the author marks Urgent.
gm_event("recall", "world.probe_gm_beats.beat.recall", "on_recall")
    .repeatable()
    .attention_band("urgent");

// A beat behind an authored gate. Its `when` is the ordinary trigger-level
// predicate, so it is ineligible until the gate opens and ineligible again
// once it closes - without the beat ever being spent.
gm_event("storm", "world.probe_gm_beats.beat.storm", "on_storm").when("flag(storm_ready)");

// The two beats that work that gate, so a test moves the world through the
// world's own handlers instead of writing flags behind its back.
gm_event("open_gate", "world.probe_gm_beats.beat.open_gate", "on_open_gate").repeatable();
gm_event("close_gate", "world.probe_gm_beats.beat.close_gate", "on_close_gate").repeatable();

// An ordinary automatic moment that a Game Master may ALSO reach for. It has
// all three levers, so its row can prove that opening it offers exactly the
// controls the author declared - and it is the only beat here that would
// arrive on its own, so it gets the "early" sentence rather than the manual one.
on_timer(600, "on_relief")
    .gm_controls("relief", "world.probe_gm_beats.beat.relief")
    .pauseable()
    .skip()
    .attention_band("background");

fn on_brief(ctx) { ctx.flags.increment("briefed", 1); }
fn on_recall(ctx) { ctx.flags.increment("recalled", 1); }
fn on_storm(ctx) { ctx.flags.increment("stormed", 1); }
fn on_open_gate(ctx) { ctx.flags.increment("storm_ready", 1); }
fn on_close_gate(ctx) { ctx.flags.increment("storm_ready", -1); }
fn on_relief(ctx) { ctx.flags.increment("relieved", 1); }
"""

