base_files.assets/worlds/probe_narrative.toml:
# Probe world for issues #1338, #1342 and #1344 — the authored mission timeline,
# the ship's-computer message and the post-mission report, end to end.
#
# No combat, no traffic, no hazard. Every event this world produces is one a
# SCENARIO AUTHOR asked for, which is the whole claim PRD #1337 makes about the
# narrative surface: the timeline is the story the world chose to tell, not a
# second copy of the damage log. A run of this world with nothing but a player
# hull and one marked civilian must produce exactly the beats listed below and
# nothing else.
#
# The authored timeline, in mission seconds:
#
#   t=1   `post` runs. Two objectives are posted (one mandatory, one not), a
#         THIRD is posted and completed in the same tick, the opening beat
#         fires, Lyra Ascending hails the crew, and the ship's computer shows
#         a short `info` message (issue #1342) that outlives no one else's
#         business — it expires on its own two seconds later.
#   t=4   `resolve` runs. The mandatory objective completes, the optional one
#         fails, and the author declares Lyra rescued — an outcome no amount of
#         simulation could have inferred, which is why it is authorable at all.
#         The ship's computer shows a second, `critical`, Station-cued message
#         (issue #1342). The SAME tick writes the run's one post-mission report
#         row (`lyra`, saved, hidden score +6): a row is written when the fate
#         is decided, not at the ending, which is what makes an inapplicable
#         row an ABSENT row rather than an invented one.
#   t=5   `resolve`'s one-second follow-up re-states that row IDENTICALLY. This
#         is the rate guard, and the assertion is a NEGATIVE one: nothing moved,
#         so the timeline must carry no second beat.
#   t=6   `window_opens` fires. Its handler records the beat that says the
#         deadline mattered.
#   t=8   `clear_the_wreck` runs. The derelict — marked, and with no authored
#         outcome — is removed with `destroy_entity`, and Lyra, already
#         declared rescued, is removed too. A THIRD computer message supersedes
#         the still-active t=4 message immediately.
#   t=10  `close_the_probe` runs. The run ends in `GamePhase::GameOver` with a
#         DECLARED defeat that is still report-bearing — and so classifies
#         `reported`, not `defeat` (issue #1344). The declaration is deliberate:
#         the flag the rows outrank is still latched, still folded and still on
#         the wire, which is the only way to prove the ranking rather than
#         assume it. The ending also clears the still-active t=8 computer
#         message — deliberately NOT a beat, because #1342's shown / superseded
#         / expired trio does not include a mission-end clear.
#
# Every one of those reaches the headless run report's `narrative` field and,
# under `--format ndjson`, the inline stream — except `report_row_updated`,
# which is folded but never streamed because a re-scored row is a rate — plus
# `marked_entity_spawned` for each marked hull on the tick it enters the world,
# and `comms_opened` on the tick Lyra's hail lands. The unmarked player hull
# produces no entity beat at all: marking is the gate, and this world proves it
# by leaving the player unmarked.
#
# THE TWO REPORT BEATS, and why one of them is a count of one:
#
#   * `report_row_updated` fires ONCE, at t=4. The identical re-statement at t=5
#     moves nothing, so it writes nothing — a re-scored row is a rate, and the
#     ndjson stream drops this kind entirely for that reason while the folded
#     timeline still counts it.
#   * `report_finalized` fires ONCE, at t=10, carrying the ending's reason id
#     (`world.probe_narrative.game_over.closed`), the row count and the hidden
#     total. It fires only because the report is non-empty: an ending that
#     authored no report is not a report-bearing ending.
#
# The score itself never leaves the host. It is on the row here and in the
# headless run report, and it is absent by construction from
# `core::messages::GameOverReportRow` — the shape both player surfaces render.
#
# THE TWO REMOVALS AT t=8 ARE THE POINT OF THE DERELICT. A scripted
# `destroy_entity` writes no combat event — an authorial removal is not a kill,
# and must never enter the combat ledger — so the timeline records it from the
# scripted-removal signal instead, and only when the author said nothing else:
#
#   * the derelict has no authored outcome, so it records `marked_entity_destroyed`;
#   * Lyra was declared `rescued` four seconds earlier, so her removal records
#     NOTHING and the rescue stands alone.
#
# Without that pair, a scenario could remove a marked hull and leave it in the
# timeline with a spawn and no fate at all.
#
# THE THREE SHOW_MESSAGE CALLS (issue #1342) exercise all three ship's-computer
# lifecycle events on one authoritative "latest only" message: `debris_notice`
# (t=1, 2s duration) EXPIRES on its own before `resolve` ever runs; `charge_ready`
# (t=4, 10s duration, Station "tactical") is still active when `clear_the_wreck`
# shows a third message at t=8, so it is SUPERSEDED rather than expiring; the
# third message is simply SHOWN, outlives its own 300s duration, and is cleared
# without a beat when the mission ends at t=10. So the timeline carries three
# `computer_message_posted` and exactly TWO `computer_message_cleared`.
#
# THE PLAYER HULL IS A COURIER, not the destroyer the other probes fly, and the
# reason is `[comms_console.ai]`: a headless run has no human on Comms, so the
# only way a *choice* gets made is the Comms AI submitting the same admitted
# `RespondToMessage` a console would. The destroyer authors no such policy and
# would leave Lyra's hail unanswered forever.

[global]
seed = 1338
ai_helm_tick_hz = 30.0
title = "world.probe_narrative.global.title"
description = "world.probe_narrative.global.description"

[player_spawn]
position = [0.0, 0.0, 0.0]

# The player ship — AI-backfilled in a headless run.
[[entity]]
template_path = "assets/entities/alliance_courier.toml"
id = "player-ship"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

# The marked entity. `narrative = true` is the author saying "this hull is part
# of the story"; without it she would spawn, hail, and be declared rescued
# without a single line of it reaching the timeline.
#
# Parked 120 units off so her hail is comfortably inside comms range for the
# whole run — an out-of-range sender's responses are greyed, and a probe that
# depended on the crew drifting into range would be testing helm, not the
# timeline.
[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "lyra"
name = "world.probe_narrative.entity.lyra.name"
narrative = true
transform = { position = [120.0, 0.0, 0.0] }
overrides = { comms = { hailable = true } }

# The derelict. Marked exactly as Lyra is, and never spoken about again: the
# script simply removes it at t=8. That is the case the timeline used to lose —
# a hull the story introduced and the story took away, with nothing in between.
[[entity]]
template_path = "assets/entities/ship_civilian_hauler.toml"
id = "wreck"
name = "world.probe_narrative.entity.wreck.name"
narrative = true
transform = { position = [-120.0, 0.0, 0.0] }

# The clock. One named deadline, visible, with a handler that records the beat.
[[deadline]]
id = "window_opens"
label = "world.probe_narrative.deadline.window_opens.label"
due_secs = 6
visible = true

[script]
setup = """
on_timer(1, "post");
on_timer(4, "resolve");
on_timer(8, "clear_the_wreck");
on_timer(10, "close_the_probe");
on_deadline("window_opens", "on_window_opens");

// The opening. Two objectives, one authored beat, one hail.
fn post(ctx) {
    ctx.effects.add_objective(#{
        id: "hold_the_channel",
        text: "world.probe_narrative.objective.hold_the_channel",
        mandatory: true,
    });
    ctx.effects.add_objective(#{
        id: "log_the_wreck",
        text: "world.probe_narrative.objective.log_the_wreck",
        mandatory: false,
    });
    // Posted and resolved inside ONE tick. The timeline must carry both beats:
    // a recorder that only diffed the tick's end state would report the
    // completion and silently swallow the posting.
    ctx.effects.add_objective(#{
        id: "sound_off",
        text: "world.probe_narrative.objective.sound_off",
        mandatory: false,
    });
    ctx.effects.complete_objective("sound_off");
    ctx.effects.narrative_beat("probe_opening");
    // issue #1342: a short-lived message that expires on its own, well before
    // `resolve` ever runs.
    ctx.effects.show_message(
        "debris_notice",
        "world.probe_narrative.computer_message.debris",
        "info",
        2,
    );
    ctx.effects.open_comms(#{
        from: "world.probe_narrative.entity.lyra.name",
        node_fn: "lyra_hails",
        urgent: true,
    });
}

// One node, one response, so the Comms AI's pick is unambiguous.
fn lyra_hails(ctx) {
    #{
        message: "world.probe_narrative.comms.lyra_hails",
        responses: [
            #{ text: "world.probe_narrative.comms.stand_by", on_pick: "on_stand_by" },
        ],
    }
}

// A terminal response: it records its own beat and ends the thread.
fn on_stand_by(ctx) {
    ctx.effects.narrative_beat("probe_answered");
}

// The resolution. One objective each way, and the author's judgement on Lyra.
fn resolve(ctx) {
    ctx.effects.complete_objective("hold_the_channel");
    ctx.effects.fail_objective("log_the_wreck");
    ctx.effects.narrative_outcome("world.probe_narrative.entity.lyra.name", "rescued");
    // issue #1342: a long-lived, Station-cued message — still active four
    // seconds later, at t=8, so `clear_the_wreck` supersedes it rather than
    // its expiring on its own.
    ctx.effects.show_message(
        "charge_ready",
        "world.probe_narrative.computer_message.charge",
        "critical",
        10,
        "tactical",
    );
    // The post-mission report row (issue #1344), written on the tick her fate
    // is decided rather than at the ending — which is what makes an
    // inapplicable row an ABSENT row rather than an invented one.
    ctx.effects.report_row(#{
        id: "lyra",
        heading: "world.probe_narrative.report.lyra.heading",
        outcome: "world.probe_narrative.report.lyra.saved",
        state: "saved",
        score: 6,
    });
    // Re-stated identically on the next tick. Nothing moved, so the timeline
    // must carry ONE report_row_updated beat and not two — the rate guard the
    // ndjson stream policy exists for.
    ctx.schedule.after(1, |ctx| {
        ctx.effects.report_row(#{
            id: "lyra",
            heading: "world.probe_narrative.report.lyra.heading",
            outcome: "world.probe_narrative.report.lyra.saved",
            state: "saved",
            score: 6,
        });
    });
}

fn on_window_opens(ctx) {
    ctx.effects.narrative_beat("probe_deadline_beat");
}

// The two scripted removals. Neither writes a combat event; the derelict still
// gets its death, and Lyra — already rescued — does not.
fn clear_the_wreck(ctx) {
    ctx.effects.destroy_entity("world.probe_narrative.entity.wreck.name");
    ctx.effects.destroy_entity("world.probe_narrative.entity.lyra.name");
    // issue #1342: supersedes "charge_ready", which is still active. A long
    // duration so it genuinely outlives the probe's run window rather than
    // expiring in turn.
    ctx.effects.show_message(
        "wreck_cleared",
        "world.probe_narrative.computer_message.wreck_cleared",
        "advisory",
        300,
    );
}

// The ending, DECLARED a defeat and still report-bearing (issue #1344). The
// declaration is deliberate: the run classifies `reported`, not `defeat`, and
// the flag it outranks is still latched, still folded and still on the wire.
fn close_the_probe(ctx) {
    ctx.effects.game_over("world.probe_narrative.game_over.closed", "defeat");
}
"""

base_files.assets/worlds/probe_transporter.toml:
# Probe world for issue #1348 — civilian discovery by scan and rescue by
# transporter, end to end.
#
# One rescuing hull (the Alliance Destroyer, which carries both the sensor suite
# that discovers the life signs and the Engineering transporter that recovers
# them) and one stranded lighter carrying four civilians, positioned close enough
# to scan and to transport. There is no scripted scan and no scripted transport:
# the destroyer is a backfilled player ship, so the headless test drives the
# discovery through the ordinary admitted `ScanTarget` path and the rescue through
# the ordinary admitted `TransportSelectContact` / `StartTransport` path — the
# only way to prove both ride the same admission a console's own controls would.
#
# WHAT THIS WORLD PROVES:
#
#   1. THE COMPUTER ANNOUNCES LIFE SIGNS ONLY AFTER THE SCAN. The rescue objective
#      and the "life signs detected" cue are chained off `scan.lighter.taken`, the
#      flag `tick_scans` latches the first time a reading of the lighter lands, so
#      neither can appear before the crew have actually looked.
#
#   2. THE TRANSPORTER RECOVERS THE CIVILIANS OVER TIME. Once discovered and in
#      range, `StartTransport` recovers the lighter's four civilians at the
#      authored rate; the rescue completes, `rescue.lighter.recovered` rises, and
#      the objective and report row resolve off it.
#
#   3. A LOST CONTACT IS A CASUALTY. If the lighter is destroyed with civilians
#      still aboard, `rescue.lighter.lost` rises and the report records the loss —
#      the human-fire consequence, reached only by a human (Backfill Tactical
#      excludes the civilian-carrying contact from its own fire).
#
# Nothing here is authored anywhere but the destroyer's own `[transporter]` /
# `[scan]` tables and the lighter's `[civilian_rescue]` / `[infrastructure]`
# tables — no scenario text, no hardcoded range, rate or count.

[global]
seed = 1348
ai_helm_tick_hz = 30.0

[player_spawn]
position = [0.0, 0.0, 0.0]

# The rescuing hull — the backfilled player ship, spawned at game start.
[[entity]]
template_path = "assets/entities/alliance_destroyer.toml"
id = "player-ship"
name = "world.probe_transporter.entity.destroyer.name"
transform = { position = [0.0, 0.0, 0.0] }
spawn_on = "game_start"

# The stranded lighter — 100 units off, inside the destroyer's 120-unit detailed
# scan band and well inside the transporter's 500-unit reach. Its authored
# `[civilian_rescue]` count and `[infrastructure]` condition ride the template;
# the world only places it. The `id` is what the discovery and rescue flags are
# keyed on: `scan.lighter.taken`, `rescue.lighter.recovered`, `rescue.lighter.lost`.
[[entity]]
template_path = "assets/entities/stranded_lighter.toml"
id = "lighter"
name = "world.probe_transporter.entity.lighter.name"
transform = { position = [100.0, 0.0, 0.0] }

[script]
setup = """
on_flag_set("scan.lighter.taken", "on_civilians_discovered");
on_flag_set("rescue.lighter.recovered", "on_rescue_complete");
on_flag_set("rescue.lighter.lost", "on_civilians_lost");

// Discovery: posts ONLY after the scan flag latches, which is the whole "the
// computer announces life signs only after the revealing scan" claim. The
// objective carries a Rescue directive so a backfilled Engineering seat serves
// it through the same transporter commands a human would send.
fn on_civilians_discovered(ctx) {
    ctx.effects.show_message(
        "world.probe_transporter.cue.life_signs",
        "world.probe_transporter.cue.life_signs",
        "advisory",
        8
    );
    ctx.effects.add_objective(#{
        id: "obj-rescue-civilians",
        text: "world.probe_transporter.objective.rescue.text",
        mandatory: true,
        source: "mission",
        base_priority: 60,
        directive_kind: "Rescue",
        target: "world.probe_transporter.entity.lighter.name",
        targets: ["world.probe_transporter.entity.lighter.name"],
    });
}

// Completion: the transporter raises `rescue.lighter.recovered` the tick the
// last civilian is aboard, and the objective and the saved report row resolve
// off that fact — the scenario, not the engine, decides the consequence.
fn on_rescue_complete(ctx) {
    ctx.effects.complete_objective("obj-rescue-civilians");
    ctx.effects.show_message(
        "world.probe_transporter.cue.rescue_complete",
        "world.probe_transporter.cue.rescue_complete",
        "info",
        8
    );
    ctx.effects.report_row(#{
        id: "civilians",
        heading: "world.probe_transporter.report.civilians.heading",
        outcome: "world.probe_transporter.report.civilians.saved",
        state: "saved",
        score: 6,
    });
}

// Casualty: the transporter raises `rescue.lighter.lost` when the lighter is
// destroyed with civilians still aboard, and the failed objective and lost
// report row are this scenario's consequence for it.
fn on_civilians_lost(ctx) {
    ctx.effects.fail_objective("obj-rescue-civilians");
    ctx.effects.show_message(
        "world.probe_transporter.cue.civilians_lost",
        "world.probe_transporter.cue.civilians_lost",
        "critical",
        8
    );
    ctx.effects.report_row(#{
        id: "civilians",
        heading: "world.probe_transporter.report.civilians.heading",
        outcome: "world.probe_transporter.report.civilians.lost",
        state: "lost",
        score: -6,
    });
}
"""

base_files.assets/worlds/probe_window.toml:
# Probe world for issue #1042 — a transfer window, the arithmetic that prices
# it, and the rule that ends it.
#
# `falling_skyway.toml` authors the SCENE: three claimants, a chain that cannot
# carry all of them, and a captain who has to choose. This world authors the
# MECHANISM under it, in the shape every probe in this family uses — an
# experiment beside a control that differs in exactly one authored fact.
#
# ── The four chains, and what each one isolates ──────────────────────────────
#
# Supply is `min(what the head can lift, what the ladder puts in it)`, and a
# rung delivers only if it is above its OWN operational line AND the people who
# staff it are at work. That is three clauses and a `min`, so there are four
# ways to be short and this world fields all of them at once, priced in the same
# beat by the same script function with different arguments:
#
#   full     head 2 berths x 20 = 40, ladder 30 + 12 = 42   ->  40   HEAD binds
#   struck   the second rung's people are OUT                ->  30   ladder binds
#   low      the second rung is UNDER ITS OWN LINE           ->  30   ladder binds
#   dead     the head is not certified to lift               ->   0   nothing
#
# `full` and `struck`/`low` bind on OPPOSITE SIDES of the `min`, which is the
# claim the pairing exists to make: the smaller of the two is genuinely the
# smaller of the two, and not the ladder every time with the head as decoration.
# `struck` and `low` differ from `full` in exactly one authored fact each — a
# `workforce` and a `condition` — so a rung that fails is a rung that failed for
# the reason under test.
#
# NO COMBAT. Nothing here is hostile, nothing is armed at anything, and the
# player's hull is parked six kilometres away: a run that produces a shot has
# gone wrong.
#
# ── The window, and the ledger it keeps ─────────────────────────────────────
#
# Everything runs against `manifest_full`, which is the only one carrying claims.
# Four claimants totalling 50 against a supply of 40, so the window is short by
# ten and the last one asked for cannot have it.
#
# Timeline (60 Hz), in mission seconds:
#
#   t=10  `probe_window_opens`. All four supplies are computed and published
#         onto their manifests; the demand and the shortfall land on the full
#         one. Before this tick every register reads its authored zero — a
#         figure the mission has not earned is not a figure on a panel.
#   t=12  ALPHA (10) is booked. 40 - 10 = 30 left, 10 committed.
#   t=20  alpha's climber reaches the top INSIDE the window. SERVED.
#   t=26  BETA (15) is booked, with four seconds left. 15 left, 25 committed.
#   t=27  GAMMA (20) is asked for and REFUSED SHORT: 20 against 15.
#   t=30  `probe_window_closes`. The window shuts, the lift on offer goes with
#         it, and the available row is zero from this tick.
#   t=32  DELTA (5) is asked for and REFUSED SHUT — the OTHER refusal, and the
#         reason this world fields a fourth claimant at all. Each claimant's
#         seam is a single ask, so the mission world cannot reach this rung with
#         only three.
#   t=34  beta's climber would have reached the top. THE AUTHORED CLOSE RULE:
#         it is STOOD DOWN rather than completed or part-paid. Beta is not
#         served, and its fifteen comes back off the committed row, which ends
#         the run at 10 — what actually went up, not what was booked.
#
# ── What this world is really testing ───────────────────────────────────────
#
# `ctx.effects.adjust_capacity` (issue #1042), which is the only new engine
# surface the slice adds. Every number below is a published
# `[[infrastructure.capacity]]` level that a SCRIPT worked out and wrote — the
# first thing in this codebase to move a capacity without a `transfer`
# completing — so a run where the registers stay at their authored zeros is a
# run where the verb did nothing, and a run where they drift is one where the
# delta arithmetic is wrong.
#
# The capacities carry NO labels, deliberately. This world publishes data and
# not prose; #1030's second gate is `probe_dossier`'s to prove, and that the
# mission's own rows reach a fact sheet is asserted in the Falling Skyway tests.
#
# BASELINE (this world is new in #1042, so this is its first recorded digest):
# `--seed 42 --ticks 2400` gives final digest 0x76d86be18703c4e7
# (8563713307821982951), and 3884973033775218574 at tick 0. Measured on a clean
# tree at the commit that added this line. It is a NEW number, not a preserved
# one — nothing to compare it against yet — so it is written down here to be the
# thing a later change is A/B'd against, the way the other probes' already are.
#
# What legitimately moves it: this file's entity list, the authored conditions
# and capacities, the deadline times, and any engine change to what the digest
# folds. The window's own bookkeeping IS in the digest, unlike most scenario
# state, and that is the point of the world: a capacity level is folded by
# `fold_infrastructure_namespace`, so every register below is a number the
# authoritative digest can see.
#
# RECORDED PRE-#1086, AND NO LONGER REPRODUCIBLE. "Unlike most scenario state"
# was true of the fold this was measured against; it is not true of this one.
# Issue #1086's `sim_digest::fold_scenario_records` now walks the two
# `[[deadline]]` entries above by name and time, the `probe_window_open`/
# `probe_window_supply`/`claim_*` flags the script sets, and the four
# `on_timer` trigger latches — none of which folded when 8563713307821982951
# was measured. Re-measure before treating it as a baseline again.
#
# WHAT DOES NOT MOVE IT: `skyhook.toml` growing thresholds. This is the only
# probe that fields a skyhook, and the collapse slice (#1040) added three warning
# rungs to that template — which lengthens the fold row of every head that
# inherits them. Both heads below override `[[infrastructure.threshold]]` per
# instance, and an instance override REPLACES an array wholesale, so each carries
# exactly the one flag it declares and this world's number is unchanged. That is
# not luck: two heads in one world MUST override, because a threshold flag is the
# scenario's namespace and two of them sharing `skyhook_lift_capable` would be
# declaring one flag between them.

[global]
seed = 1042
ai_helm_tick_hz = 30.0

# ── The two sides ────────────────────────────────────────────────────────────
#
# `probe_window_pickets` are out and stay out; `probe_window_crews` never were.
# One rung each, and that one authored word is the only difference between them.

[[workforce]]
id = "probe_window_crews"
label = "world.probe_window.workforce.crews.label"
disposition = 60

[[workforce]]
id = "probe_window_pickets"
label = "world.probe_window.workforce.pickets.label"
on_strike = true
disposition = 20

[player_spawn]
position = [6000.0, 0.0, 6000.0]

# The player ship. Present because a world needs one; parked far enough away
# that nothing it does reaches anything under test.
[[entity]]
template_path = "assets/entities/alliance_cruiser.toml"
id = "player-ship"
transform = { position = [6000.0, 0.0, 6000.0] }
spawn_on = "game_start"

# ── The heads ────────────────────────────────────────────────────────────────
#
# Both are `skyhook.toml`, which is the template the mission fields, and both
# replace its capacity and threshold tables wholesale — because a capacity id and
# a threshold flag are the SCENARIO'S namespace, and two heads sharing
# `skyhook_lift_capable` would be declaring one flag between them and
# overwriting each other's answer every tick.
#
# `load_certified = 20` is a deliberately SMALL climber: two berths at twenty is
# forty against a forty-two-unit ladder, so the head is what binds on the `full`
# chain. The mission authors a hundred and eighty for the opposite reason.
# [ai] Unratified, like every number in this file.

[[entity]]
template_path = "assets/entities/skyhook.toml"
name = "world.probe_window.entity.head_certified.name"
transform = { position = [0.0, 0.0, 0.0] }
overrides = { infrastructure = { condition = 80.0, capacity = [
  { id = "berths_certified", amount = 2 },
  { id = "load_certified", amount = 20 },
], threshold = [
  { flag = "head_certified_lift", fails_below = 0.45 },
] } }

# The control for the head clause, and the only authored difference is thirty
# points of condition: the same template, the same berths, the same climber.
[[entity]]
template_path = "assets/entities/skyhook.toml"
name = "world.probe_window.entity.head_slipped.name"
transform = { position = [0.0, 0.0, 600.0] }
overrides = { infrastructure = { condition = 30.0, capacity = [
  { id = "berths_slipped", amount = 2 },
  { id = "load_slipped", amount = 20 },
], threshold = [
  { flag = "head_slipped_lift", fails_below = 0.45 },
] } }

# ── The rungs ────────────────────────────────────────────────────────────────
#
# Four, and each of the last three differs from `rung_up` in exactly one thing.

# The rung that works. Above its line, nobody staffing it is out.
[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.rung_up.name"
transform = { position = [400.0, 0.0, 0.0] }
overrides = { infrastructure = { condition = 80.0, capacity = [
  { id = "rung_up_lift", amount = 30 },
], threshold = [
  { flag = "rung_up_pumping", fails_below = 0.4 },
] } }

# The second rung of the `full` chain: above its line and worked by people who
# turned up.
[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.rung_worked.name"
transform = { position = [800.0, 0.0, 0.0] }
overrides = { infrastructure = { condition = 80.0, workforce = "probe_window_crews", capacity = [
  { id = "rung_worked_lift", amount = 12 },
], threshold = [
  { flag = "rung_worked_pumping", fails_below = 0.4 },
] } }

# THE PEOPLE CLAUSE. Identical to `rung_worked` in condition, throughput and
# threshold; the one authored difference is which side staffs it.
[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.rung_struck.name"
transform = { position = [800.0, 0.0, 400.0] }
overrides = { infrastructure = { condition = 80.0, workforce = "probe_window_pickets", capacity = [
  { id = "rung_struck_lift", amount = 12 },
], threshold = [
  { flag = "rung_struck_pumping", fails_below = 0.4 },
] } }

# THE CONDITION CLAUSE. Identical to `rung_worked` but for its condition, which
# is under its own authored line — so its flag is DOWN from the first tick and
# nobody had to walk out for this rung to deliver nothing.
[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.rung_low.name"
transform = { position = [800.0, 0.0, 800.0] }
overrides = { infrastructure = { condition = 20.0, workforce = "probe_window_crews", capacity = [
  { id = "rung_low_lift", amount = 12 },
], threshold = [
  { flag = "rung_low_pumping", fails_below = 0.4 },
] } }

# ── The manifests ────────────────────────────────────────────────────────────
#
# Four register-holders. Every row starts EMPTY and is written by script: this
# world's whole subject is that a scenario can work a number out and put it
# somewhere a console reads.
#
# `ceiling = 400` on each register, for the mission's reason: `adjust_capacity`
# clamps to `0..=ceiling`, so a ceiling under anything the arithmetic can produce
# would silently truncate the answer rather than fail loudly.

# The one with claims on it, and the one the booking ledger runs against.
[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.manifest_full.name"
transform = { position = [1600.0, 0.0, 0.0] }
overrides = { infrastructure = { condition = 100.0, capacity = [
  { id = "claim_alpha", amount = 10 },
  { id = "claim_beta", amount = 15 },
  { id = "claim_gamma", amount = 20 },
  { id = "claim_delta", amount = 5 },
  { id = "full_available", amount = 0, ceiling = 400 },
  { id = "full_demand", amount = 0, ceiling = 400 },
  { id = "full_shortfall", amount = 0, ceiling = 400 },
  { id = "full_committed", amount = 0, ceiling = 400 },
], threshold = [] } }

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.manifest_struck.name"
transform = { position = [1600.0, 0.0, 400.0] }
overrides = { infrastructure = { condition = 100.0, capacity = [
  { id = "struck_available", amount = 0, ceiling = 400 },
], threshold = [] } }

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.manifest_low.name"
transform = { position = [1600.0, 0.0, 800.0] }
overrides = { infrastructure = { condition = 100.0, capacity = [
  { id = "low_available", amount = 0, ceiling = 400 },
], threshold = [] } }

[[entity]]
template_path = "assets/entities/depot_transfer.toml"
name = "world.probe_window.entity.manifest_dead.name"
transform = { position = [1600.0, 0.0, 1200.0] }
overrides = { infrastructure = { condition = 100.0, capacity = [
  { id = "dead_available", amount = 0, ceiling = 400 },
], threshold = [] } }

# ── The clock ────────────────────────────────────────────────────────────────
#
# Both visible, for the mission's reason: a window a crew cannot see coming is a
# stopwatch somebody else is holding. Twenty seconds of window against an
# eight-second climber, so a booking made near the end is genuinely still on the
# ribbon when the shutters come down.

[[deadline]]
id = "probe_window_opens"
label = "world.probe_window.deadline.opens.label"
due_secs = 10
visible = true

[[deadline]]
id = "probe_window_closes"
label = "world.probe_window.deadline.closes.label"
due_secs = 30
visible = true

[script]
setup = """
on_deadline("probe_window_opens", "on_window_opens");
on_deadline("probe_window_closes", "on_window_closes");

// The four asks, on a clock rather than on a captain's finger. Each is a single
// shot, which is the mission's authored rule and the reason four claimants are
// needed to reach both refusals.
on_timer(12, "ask_alpha");
on_timer(26, "ask_beta");
on_timer(27, "ask_gamma");
on_timer(32, "ask_delta");

// ── The arithmetic, in the mission's own shape ──────────────────────────────

// One rung. Two questions, and it has to pass both.
fn rung_delivers(ctx, operational_flag, capacity_id, stoppage_flag) {
    if ctx.flags[operational_flag] == 0 { return 0; }
    if ctx.flags[stoppage_flag] > 0 { return 0; }
    ctx.flags[capacity_id]
}

// One chain: the smaller of what the head lifts and what the ladder puts in it.
// Called four times with four sets of arguments, which is what makes the four
// results a comparison rather than four scripts.
fn chain_supply(ctx, lift_flag, berths_id, load_id, ladder) {
    let head = 0;
    if ctx.flags[lift_flag] > 0 {
        head = ctx.flags[berths_id] * ctx.flags[load_id];
    }
    if head < ladder { head } else { ladder }
}

// Publish an absolute figure onto a register, as a delta off what is there.
fn publish(ctx, manifest, capacity_id, want) {
    let live = ctx.flags[capacity_id];
    if want != live {
        ctx.effects.adjust_capacity(manifest, capacity_id, want - live);
    }
}

fn on_window_opens(ctx) {
    let worked = rung_delivers(ctx, "rung_worked_pumping", "rung_worked_lift",
                               "workforce.probe_window_crews.on_strike");
    let struck = rung_delivers(ctx, "rung_struck_pumping", "rung_struck_lift",
                               "workforce.probe_window_pickets.on_strike");
    let low    = rung_delivers(ctx, "rung_low_pumping", "rung_low_lift",
                               "workforce.probe_window_crews.on_strike");
    let up     = rung_delivers(ctx, "rung_up_pumping", "rung_up_lift", "nobody_is_out");

    // THE FOUR CHAINS, priced in one beat by one function.
    let full   = chain_supply(ctx, "head_certified_lift", "berths_certified", "load_certified", up + worked);
    let picket = chain_supply(ctx, "head_certified_lift", "berths_certified", "load_certified", up + struck);
    let under  = chain_supply(ctx, "head_certified_lift", "berths_certified", "load_certified", up + low);
    let gone   = chain_supply(ctx, "head_slipped_lift", "berths_slipped", "load_slipped", up + worked);

    let demand = ctx.flags["claim_alpha"] + ctx.flags["claim_beta"] +
                 ctx.flags["claim_gamma"] + ctx.flags["claim_delta"];
    let short = demand - full;
    if short < 0 { short = 0; }

    ctx.flags.probe_window_open = 1;
    ctx.flags.probe_window_supply = full;

    publish(ctx, "world.probe_window.entity.manifest_full.name", "full_available", full);
    publish(ctx, "world.probe_window.entity.manifest_full.name", "full_demand", demand);
    publish(ctx, "world.probe_window.entity.manifest_full.name", "full_shortfall", short);
    publish(ctx, "world.probe_window.entity.manifest_struck.name", "struck_available", picket);
    publish(ctx, "world.probe_window.entity.manifest_low.name", "low_available", under);
    publish(ctx, "world.probe_window.entity.manifest_dead.name", "dead_available", gone);
}

// ── The ledger ─────────────────────────────────────────────────────────────

// Granted or refused in ONE place, against the flag ledger rather than the
// panel row: a capacity counter is re-published by the infrastructure tick, so
// two asks landing in the same tick would both read the first one's row before
// it had moved.
fn book(ctx, claim_id) {
    if ctx.flags.probe_window_open == 0 {
        ctx.flags.increment("probe_refused_shut", 1);
        return false;
    }
    let need = ctx.flags[claim_id];
    let left = ctx.flags.probe_window_supply - ctx.flags.probe_window_reserved;
    if left < need {
        ctx.flags.increment("probe_refused_short", 1);
        return false;
    }
    ctx.flags.increment("probe_window_reserved", need);
    ctx.flags.increment("probe_lifts_started", 1);
    ctx.effects.adjust_capacity("world.probe_window.entity.manifest_full.name", "full_available", -need);
    ctx.effects.adjust_capacity("world.probe_window.entity.manifest_full.name", "full_committed", need);
    true
}

// A climber reaching the top — or not. THE CLOSE RULE IS THIS BRANCH.
fn land(ctx, claim_id, served_flag, stood_down_flag) {
    if ctx.flags.probe_window_open > 0 {
        ctx.flags[served_flag] = 1;
        ctx.flags.increment("probe_lifts_landed", 1);
        return;
    }
    ctx.flags[stood_down_flag] = 1;
    ctx.flags.increment("probe_lifts_aborted", 1);
    ctx.effects.adjust_capacity(
        "world.probe_window.entity.manifest_full.name", "full_committed", -ctx.flags[claim_id]);
}

// Eight seconds a climber, so the one booked at t=26 is still on the ribbon at
// t=30 and the one booked at t=12 is long since at the top.
fn ask_alpha(ctx) {
    if book(ctx, "claim_alpha") {
        ctx.schedule.after(8, |ctx| { land(ctx, "claim_alpha", "served_alpha", "stood_down_alpha"); });
    }
}

fn ask_beta(ctx) {
    if book(ctx, "claim_beta") {
        ctx.schedule.after(8, |ctx| { land(ctx, "claim_beta", "served_beta", "stood_down_beta"); });
    }
}

fn ask_gamma(ctx) {
    if book(ctx, "claim_gamma") {
        ctx.schedule.after(8, |ctx| { land(ctx, "claim_gamma", "served_gamma", "stood_down_gamma"); });
    }
}

fn ask_delta(ctx) {
    if book(ctx, "claim_delta") {
        ctx.schedule.after(8, |ctx| { land(ctx, "claim_delta", "served_delta", "stood_down_delta"); });
    }
}

fn on_window_closes(ctx) {
    ctx.flags.probe_window_open = 0;
    ctx.flags.probe_window_closed = 1;
    let left = ctx.flags.probe_window_supply - ctx.flags.probe_window_reserved;
    if left > 0 {
        ctx.effects.adjust_capacity(
            "world.probe_window.entity.manifest_full.name", "full_available", -left);
    }
}
"""
